function solve(num, k) {
  const n = num.length;
  if (k >= n) return "0";
  if (k <= 0) {
    const only = num.replace(/^0+/, "");
    return only === "" ? "0" : only;
  }
  let dp = new Array(k + 1).fill(null);
  dp[0] = "";
  for (let i = 1; i <= n; i++) {
    const nxt = new Array(k + 1).fill(null);
    for (let j = 0; j <= k; j++) {
      let best = null;
      if (dp[j] !== null) best = dp[j] + num[i - 1];
      if (j > 0 && dp[j - 1] !== null) {
        const cand = dp[j - 1];
        if (best === null || cand < best) best = cand;
      }
      nxt[j] = best;
    }
    dp = nxt;
  }
  const res = (dp[k] === null ? "" : dp[k]).replace(/^0+/, "");
  return res === "" ? "0" : res;
}

function solve(num, k) {
  const stack = [];
  let rem = k;
  for (const ch of num) {
    while (rem > 0 && stack.length > 0 && stack[stack.length - 1] > ch) {
      stack.pop();
      rem -= 1;
    }
    stack.push(ch);
  }
  if (rem >= stack.length) {
    stack.length = 0;
  } else if (rem > 0) {
    stack.length -= rem;
  }
  const res = stack.join("").replace(/^0+/, "");
  return res === "" ? "0" : res;
}
